        return cache[word]
    for k in range(len(word) - 1):
        c, m = word[k]
        d, n = word[k + 1]
        if c == d and m == n:
            cache[word] = {}
            return cache[word]
        if c < d or (c == d and m > n):
            swapped = word[:k] + (word[k + 1], word[k]) + word[k + 2:]
            value = {w: -a for w, a in normal(swapped, cache).items()}
            if c == 0 and d == 1 and m == n:
                for w, a in normal(word[:k] + word[k + 2:], cache).items():
                    value[w] = value.get(w, 0) + a
            cache[word] = {w: a for w, a in value.items() if a}
            return cache[word]
    cache[word] = {word: 1}
    return cache[word]


